import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 법정 기준시간 설정 행의 분류·키 (입력 문서에 값이 없어 정한 값)
const LIMIT_CATEGORY = '근태';
const LIMIT_KEY = 'weekly_legal_work_hours';
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

type CurrentUser = ReturnType<typeof currentUser>;

function isManager(user: CurrentUser): boolean {
  try {
    user.require('근태 담당자');
    return true;
  } catch (e) {
    return false;
  }
}

function readRange(q: Record<string, unknown>): { startDate: string; endDate: string } {
  const startDate = typeof q['startDate'] === 'string' ? q['startDate'] : '';
  const endDate = typeof q['endDate'] === 'string' ? q['endDate'] : '';
  if (!DATE_RE.test(startDate) || !DATE_RE.test(endDate) || endDate < startDate) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간을 올바르게 입력해 주세요.');
  }
  return { startDate, endDate };
}

function readId(q: Record<string, unknown>, name: string): string | null {
  const v = q[name];
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (!/^\d+$/.test(String(v))) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 조건의 ID 형식이 올바르지 않습니다.');
  }
  return String(v);
}

function readPaging(q: Record<string, unknown>): { page: number; size: number } {
  const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
  const rawSize = q['size'] === undefined || q['size'] === '' ? 20 : Number(q['size']);
  if (!Number.isInteger(page) || page < 0 || !Number.isInteger(rawSize) || rawSize < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 정보가 올바르지 않습니다.');
  }
  return { page, size: Math.min(rawSize, 200) };
}

// 조회 범위: 근태 담당자는 전체, 임직원은 본인 기록만
function scopedEmployeeId(user: CurrentUser, requested: string | null): string | null {
  if (isManager(user)) {
    return requested;
  }
  if (requested !== null && requested !== user.id) {
    throw new ApiError(422, 'SCOPE_NOT_PERMITTED', '조회 권한 범위 밖의 요청입니다.');
  }
  return user.id;
}

const WEEKLY_CTE =
  'WITH w AS (' +
  ' SELECT c.employee_id AS employee_id,' +
  ' CAST(date_trunc(\'week\', c.work_date) AS date) AS week_start,' +
  ' COALESCE(ROUND(CAST(SUM(CASE WHEN c.check_in_at IS NOT NULL AND c.check_out_at IS NOT NULL' +
  ' THEN EXTRACT(EPOCH FROM (c.check_out_at - c.check_in_at)) ELSE 0 END) / 3600 AS numeric), 2), 0) AS hours,' +
  ' bool_or(c.check_in_at IS NULL OR c.check_out_at IS NULL) AS missing' +
  ' FROM commute_record c' +
  ' JOIN employee e ON e.employee_id = c.employee_id' +
  ' WHERE c.work_date >= CAST(:startDate AS date) AND c.work_date <= CAST(:endDate AS date)' +
  ' AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))' +
  ' AND (CAST(:employeeId AS bigint) IS NULL OR c.employee_id = CAST(:employeeId AS bigint))' +
  ' GROUP BY c.employee_id, CAST(date_trunc(\'week\', c.work_date) AS date))';

const TYPE_CTE =
  'WITH t AS (' +
  ' SELECT a.attendance_type AS attendance_type,' +
  ' COUNT(*) AS cnt,' +
  ' CAST(SUM((a.end_date - a.start_date) + 1) AS numeric) AS days' +
  ' FROM attendance_request a' +
  ' JOIN employee e ON e.employee_id = a.employee_id' +
  ' WHERE a.start_date >= CAST(:startDate AS date) AND a.start_date <= CAST(:endDate AS date)' +
  ' AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))' +
  ' AND (CAST(:employeeId AS bigint) IS NULL OR a.employee_id = CAST(:employeeId AS bigint))' +
  ' GROUP BY a.attendance_type)';

@Controller('api/v1')
export class FnSfr01806Controller {
  @Get('/work-hours/weekly')
  async listWeeklyWorkHours(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const q = checks.queryOf(req.query);
    const range = readRange(q);
    const paging = readPaging(q);
    const departmentId = readId(q, 'departmentId');
    const employeeId = scopedEmployeeId(user, readId(q, 'employeeId'));
    return transaction(async (db) => {
      const limitRows = await db.query(
        'SELECT setting_value AS "settingValue" FROM system_setting WHERE category = :category AND setting_key = :key',
        { category: LIMIT_CATEGORY, key: LIMIT_KEY },
      );
      const rawLimit = limitRows.length > 0 ? limitRows[0]['settingValue'] : null;
      const limit = rawLimit === null || rawLimit === undefined || String(rawLimit).trim() === '' ? NaN : Number(rawLimit);
      if (!Number.isFinite(limit)) {
        throw new ApiError(422, 'WORK_HOUR_LIMIT_NOT_CONFIGURED', '근태 설정에 법정 기준시간이 없습니다.');
      }
      const params = {
        startDate: range.startDate,
        endDate: range.endDate,
        departmentId,
        employeeId,
        limit: String(limit),
        size: paging.size,
        offset: paging.page * paging.size,
      };
      const items = await db.query(
        WEEKLY_CTE +
          ' SELECT employee_id AS "employeeId",' +
          ' to_char(week_start, \'YYYY-MM-DD\') AS "weekStartDate",' +
          ' hours AS "weeklyWorkHours",' +
          ' (hours > CAST(:limit AS numeric)) AS "isOverLimit",' +
          ' missing AS "hasMissingRecord"' +
          ' FROM w ORDER BY week_start, employee_id LIMIT :size OFFSET :offset',
        params,
      );
      const totalRows = await db.query(WEEKLY_CTE + ' SELECT COUNT(*) AS total FROM w', params);
      return {
        items,
        page: paging.page,
        size: paging.size,
        total: Number(totalRows[0]['total']),
      };
    });
  }

  @Get('/work-hours/type-summary')
  async listAttendanceTypeSummary(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const q = checks.queryOf(req.query);
    const range = readRange(q);
    const paging = readPaging(q);
    const departmentId = readId(q, 'departmentId');
    const employeeId = scopedEmployeeId(user, readId(q, 'employeeId'));
    return transaction(async (db) => {
      const params = {
        startDate: range.startDate,
        endDate: range.endDate,
        departmentId,
        employeeId,
        size: paging.size,
        offset: paging.page * paging.size,
      };
      const items = await db.query(
        TYPE_CTE +
          ' SELECT attendance_type AS "attendanceType", cnt AS "count", days AS "days"' +
          ' FROM t ORDER BY attendance_type LIMIT :size OFFSET :offset',
        params,
      );
      const totalRows = await db.query(TYPE_CTE + ' SELECT COUNT(*) AS total FROM t', params);
      return {
        items,
        page: paging.page,
        size: paging.size,
        total: Number(totalRows[0]['total']),
      };
    });
  }
}

