import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  Pager,
  call,
  useData,
} from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

type Tab = 'weekly' | 'type';

interface Cond {
  startDate: string;
  endDate: string;
  departmentId: number | string;
  employeeId: number | string;
}

const EMPTY: Cond = { startDate: '', endDate: '', departmentId: '', employeeId: '' };
const SIZE = 20;

export default function FnSfr01806Page({ role }: PageProps) {
  const [tab, setTab] = useState<Tab>('weekly');
  const [draft, setDraft] = useState<Cond>(EMPTY);
  const [applied, setApplied] = useState<Cond | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [message, setMessage] = useState('');

  const { data, error, loading } = useData<Page | undefined>(async () => {
    if (!applied) {
      return undefined;
    }
    const path = tab === 'weekly' ? '/work-hours/weekly' : '/work-hours/type-summary';
    return call<Page>('GET', path, role, undefined, {
      startDate: applied.startDate,
      endDate: applied.endDate,
      departmentId: applied.departmentId,
      employeeId: applied.employeeId,
      page: pageNo,
      size: SIZE,
    });
  }, [tab, applied, pageNo, role]);

  function search() {
    if (!draft.startDate || !draft.endDate) {
      setMessage('조회 시작일과 종료일을 입력해 주세요.');
      return;
    }
    if (draft.endDate < draft.startDate) {
      setMessage('종료일은 시작일 이후여야 합니다.');
      return;
    }
    setMessage('');
    setPageNo(0);
    setApplied({ ...draft });
  }

  function reset() {
    setDraft(EMPTY);
    setApplied(null);
    setPageNo(0);
    setMessage('');
  }

  function changeTab(next: Tab) {
    setTab(next);
    setPageNo(0);
  }

  const weeklyColumns: Column[] = [
    { key: 'employeeId', label: '임직원', render: (row: Row) => <RefNameCell role={role} value={row.employeeId} /> },
    { key: 'weekStartDate', label: '주 시작일', render: (row: Row) => <DateText value={row.weekStartDate} /> },
    { key: 'weeklyWorkHours', label: '주간 합계 근무시간', render: (row: Row) => <Num value={row.weeklyWorkHours} /> },
    { key: 'isOverLimit', label: '법정 기준시간 초과 여부', render: (row: Row) => <Badge value={row.isOverLimit ? '초과' : '정상'} /> },
    { key: 'hasMissingRecord', label: '출퇴근 데이터 누락 여부', render: (row: Row) => <Badge value={row.hasMissingRecord ? '누락' : '정상'} /> },
  ];

  const typeColumns: Column[] = [
    { key: 'attendanceType', label: '근태 유형' },
    { key: 'count', label: '유형별 건수', render: (row: Row) => <Num value={row.count} /> },
    { key: 'days', label: '유형별 일수', render: (row: Row) => <Num value={row.days} /> },
  ];

  const rows = data ? data.items : [];
  const empty = applied ? '조회 조건에 해당하는 내역이 없습니다.' : '조회 기간을 선택한 뒤 조회해 주세요.';

  return (
    <div className="doc">
      <section className="box">
        <h2>근무시간 현황</h2>
        <div>
          <button className={tab === 'weekly' ? '' : 'ghost'} onClick={() => changeTab('weekly')}>
            주간 근무시간
          </button>
          <button className={tab === 'type' ? '' : 'ghost'} onClick={() => changeTab('type')}>
            근태 유형별 집계
          </button>
        </div>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={draft.startDate} onChange={(v) => setDraft({ ...draft, startDate: v })} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={draft.endDate} onChange={(v) => setDraft({ ...draft, endDate: v })} />
          </Field>
          <Field label="부서 ID">
            <LookupSelect
              table="department"
              role={role}
              value={draft.departmentId}
              onChange={(v) => setDraft({ ...draft, departmentId: v })}
            />
          </Field>
          <Field label="임직원 ID">
            <LookupSelect
              table="employee"
              role={role}
              value={draft.employeeId}
              onChange={(v) => setDraft({ ...draft, employeeId: v })}
            />
          </Field>
        </Filters>
        {message ? <ErrorText text={message} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0} />
        <DataTable columns={tab === 'weekly' ? weeklyColumns : typeColumns} rows={loading ? [] : rows} empty={empty} />
        {data ? <Pager page={data.page} size={data.size} total={data.total} onPage={setPageNo} /> : null}
      </section>
    </div>
  );
}

function RefNameCell({ role, value }: { role: string; value: unknown }) {
  return <RefName table="employee" role={role} value={value} />;
}
